lines=[];offset=0
for i,line in enumerate(log.splitlines(keepends=True),1):
 text=ansi.sub(b'',line).decode('utf-8','replace').rstrip(chr(13)+chr(10))
 lines.append((i,offset,text));offset+=len(line)
